spec fn sticky(s: i64, r: i64) -> bool { (s == 2 || s == 3) ==> r == s }

#[effects(pure)]
#[uses(d043, sticky)]
fn d046(s: i64, ev: i64) -> (r: i64)
    requires d043(s),
    ensures d043(r), sticky(s, r),
{
    if s == 0 {
        if ev == 1 {
            1
        } else {
            0
        }
    } else {
        if s == 1 {
            if ev == 2 {
                2
            } else {
                if ev < 0 {
                    3
                } else {
                    1
                }
            }
        } else {
            s
        }
    }
}

#[effects(pure)]
#[uses(d043, sticky)]
fn d042(events: &[i64], s0: i64) -> (r: i64)
    requires d043(s0),
    ensures d043(r), sticky(s0, r),
{
    let mut s: i64 = s0;
    let mut k: usize = 0;
    while k < events.len()
        invariant k <= events.len(), d043(s), sticky(s0, s),
        decreases events.len() - k,
    {
        s = d046(s, events[k]);
        k = k + 1;
    }
    s
}
